using System;
using System.Collections.Generic;
using Febucci.UI;
using LittleLeo.Events;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class EventsPanel : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private TextMeshProUGUI eventNameText;

	[SerializeField]
	private TextMeshProUGUI eventText;

	[SerializeField]
	private TextAnimatorPlayer eventTextAnimatorPlayer;

	[SerializeField]
	private FadeCanvasGroup eventTextFadeCanvasGroup;

	[SerializeField]
	private CanvasGroup eventTextCanvasGroup;

	[SerializeField]
	private Transform eventButtonsHolder;

	[SerializeField]
	private GameObject eventButtonPrefab;

	[SerializeField]
	private Transform eventSpriteGameObjectHolder;

	[SerializeField]
	private FadeCanvasGroup fadeCanvasGroup;

	[SerializeField]
	private CanvasGroup backgroundPurpleForTransition;

	[SerializeField]
	private float delayToShowText = 0.3f;

	[SerializeField]
	private float textsUpdateFadeOutDuration = 0.2f;

	[SerializeField]
	private float delayToUpdateEventText = 0.3f;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnShowBackButtonHideSkipButtonDiceRewardEvent;

	public Action<EventAction> onEventButtonPressed;

	private float defaultEventTextSize;

	private GameObject eventSpriteGameObject;

	private ButtonCustomEventSetup buttonCustomEventSetup;

	private bool callOnEventButtonPressedButDontStoreEventsPanelState;

	private bool storeWhenEnteredMap;

	private int buttonPressedIndex;

	private Action comingBackFromFadeAction;

	public GameObject EventSpriteGameObject => eventSpriteGameObject;

	public void SetComingBackFromFadeAction(Action comingBackFromFadeAction)
	{
		this.comingBackFromFadeAction = comingBackFromFadeAction;
	}

	private void Awake()
	{
		defaultEventTextSize = eventText.fontSize;
		ReferenceSingleton<PoolHandler>.Instance.AddPool(eventButtonPrefab);
	}

	public void Initialize(ButtonCustomEventSetup buttonCustomEventSetup)
	{
		fadeCanvasGroup.CanvasGroup.interactable = true;
		this.buttonCustomEventSetup = buttonCustomEventSetup;
		backgroundPurpleForTransition.ignoreParentGroups = false;
		if (eventSpriteGameObject != null)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(eventSpriteGameObject);
		}
		eventSpriteGameObject = buttonCustomEventSetup.SpawnEventSpritesGameObject(eventSpriteGameObjectHolder);
		if (eventSpriteGameObject.TryGetComponent<EventVisualFeedback>(out var component))
		{
			component.Initialize(this);
		}
		base.gameObject.SetActive(value: true);
		eventNameText.SetText(buttonCustomEventSetup.EventName);
		eventTextFadeCanvasGroup.CanvasGroup.alpha = 1f;
		if (LanguagesIndexes.IsCurrentLanguageRussian() && buttonCustomEventSetup.EnableRussianLanguageCustomEventTextSize)
		{
			eventText.fontSize = buttonCustomEventSetup.RussianLanguageCustomEventTextSize;
		}
		else
		{
			eventText.fontSize = defaultEventTextSize;
		}
		eventText.SetText(buttonCustomEventSetup.EventDescription);
		InvokeAlternatives.Invoke(this, delayToShowText, delegate
		{
			StartShowingEventText();
		});
		StoreAllButtons();
		InvokeAlternatives.InvokeAfterFrame(this, delegate
		{
			EventButtonData[] eventButtonDatas = buttonCustomEventSetup.GetEventButtonDatas();
			for (int i = 0; i < eventButtonDatas.Length; i++)
			{
				InitializeButton(eventButtonDatas[i], i, delayToShowText, firstInitialize: true);
			}
			InvokeAlternatives.InvokeAfterFrame(this, delegate
			{
				LayoutRebuilder.ForceRebuildLayoutImmediate(eventButtonsHolder.GetComponent<RectTransform>());
				fadeCanvasGroup.Fade(toggle: true);
				CheckJoystick();
			});
		});
	}

	private void CheckJoystick()
	{
		ReferenceSingleton<InputManager>.Instance.InitializeEventJoystickInput(this);
	}

	public void StoreAllButtons()
	{
		List<Transform> children = eventButtonsHolder.GetChildren();
		for (int i = 0; i < children.Count; i++)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(children[i].gameObject);
		}
	}

	public void SetButtonTextsToEmptyAndAlphaCanvasGroupToZero()
	{
		List<Transform> children = eventButtonsHolder.GetChildren();
		for (int i = 0; i < children.Count; i++)
		{
			children[i].GetComponent<EventButton>().SetTextsToEmptyAndAlphaCanvasGroupToZero();
		}
	}

	private void FadeCanvasGroupButtons()
	{
		List<Transform> children = eventButtonsHolder.GetChildren();
		for (int i = 0; i < children.Count; i++)
		{
			children[i].GetComponent<EventButton>().FadeCanvasGroupFadeOut();
		}
	}

	private void InitializeButton(EventButtonData eventButtonData, int i, float customDelayToShowText, bool firstInitialize, bool useLoreSuccess = false, bool useLoreFailure = false)
	{
		if (useLoreSuccess)
		{
			eventButtonData.SetLoreTextID(buttonCustomEventSetup.GetEventButtonLoreDescriptionSuccessID(eventButtonData.GetEventButtonDataIDIndex(i)));
		}
		else if (useLoreFailure)
		{
			eventButtonData.SetLoreTextID(buttonCustomEventSetup.GetEventButtonLoreDescriptionFailureID(eventButtonData.GetEventButtonDataIDIndex(i)));
		}
		else
		{
			eventButtonData.SetLoreTextID(buttonCustomEventSetup.GetEventButtonLoreDescriptionID(eventButtonData.GetEventButtonDataIDIndex(i)));
		}
		eventButtonData.SetResultTextID(buttonCustomEventSetup.GetEventButtonResultDescriptionID(eventButtonData.GetEventButtonDataIDIndex(i)));
		ReferenceSingleton<PoolHandler>.Instance.GetObject(eventButtonPrefab.name, eventButtonsHolder).GetComponent<EventButton>().Initialize(eventButtonData, this, i, customDelayToShowText, firstInitialize, textsUpdateFadeOutDuration);
	}

	public void Initialize(string rewardName, Reward[] rewards)
	{
		base.gameObject.SetActive(value: true);
		eventNameText.SetText(rewardName);
		InvokeAlternatives.InvokeAfterMultipleFrames(this, 3, delegate
		{
			for (int i = 0; i < rewards.Length; i++)
			{
				UnityEngine.Object.Instantiate(eventButtonPrefab, eventButtonsHolder).GetComponent<EventButton>().Initialize(rewards[i]);
			}
		});
	}

	public void EventButtonPressedFadeOutEventsPanel(bool dontStoreAfterFadeOut = false, float storeEventsPanelDelay = 0f, bool ignoreDisableRewardsAnimation = false)
	{
		if (dontStoreAfterFadeOut)
		{
			callOnEventButtonPressedButDontStoreEventsPanelState = true;
			ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value: true);
		}
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation || ignoreDisableRewardsAnimation)
		{
			fadeCanvasGroup.Fade(toggle: false, delegate
			{
				if (!dontStoreAfterFadeOut)
				{
					if (storeEventsPanelDelay > 0f)
					{
						InvokeAlternatives.Invoke(this, storeEventsPanelDelay, delegate
						{
							ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
						});
					}
					else
					{
						ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
					}
				}
			});
		}
		else
		{
			fadeCanvasGroup.Fade(toggle: false, delegate
			{
				ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value: true);
			});
			storeWhenEnteredMap = true;
		}
	}

	public void ToggleBackgroundPurpleForTransitionIgnoreParentGroups(bool value)
	{
		backgroundPurpleForTransition.ignoreParentGroups = value;
	}

	public void EventButtonPressedUpdateEventDescriptionAndButtons(int buttonIndex, bool instantlyUpdate, EventButtonData customEventButtonOnUpdate, string customEventText = "", bool useLoreSuccess = false, bool useLoreFailure = false)
	{
		if (instantlyUpdate)
		{
			FadeCanvasGroupButtons();
			eventTextFadeCanvasGroup.Fade(toggle: false, delegate
			{
				if (customEventText != "")
				{
					eventText.SetText(customEventText);
				}
				else
				{
					eventText.SetText(buttonCustomEventSetup.GetButtonPressedEventDescription(buttonIndex));
				}
				StoreAllButtons();
				if (customEventButtonOnUpdate != null)
				{
					InitializeButton(customEventButtonOnUpdate, buttonIndex, -1f, firstInitialize: false, useLoreSuccess, useLoreFailure);
				}
				else
				{
					InitializationLastButton(-1);
				}
				InvokeAlternatives.InvokeAfterFrame(this, delegate
				{
					eventTextCanvasGroup.alpha = 1f;
					StartShowingEventText();
					StartShowingLastButtonText();
					CheckJoystick();
				});
			}, textsUpdateFadeOutDuration);
		}
		else
		{
			buttonPressedIndex = buttonIndex;
		}
	}

	private void InitializationLastButton(int customDelayToShowText)
	{
		InitializeButton(buttonCustomEventSetup.GetEventButtonDatas().Last(), buttonCustomEventSetup.GetEventButtonDatas().Length - 1, customDelayToShowText, firstInitialize: false);
	}

	private void StartShowingLastButtonText()
	{
		eventButtonsHolder.GetLastChild().GetComponent<EventButton>().StartShowingButtonTexts();
	}

	private void StartShowingEventText()
	{
		eventTextAnimatorPlayer.StartShowingText(resetVisibleCharacters: true);
	}

	public void EventButtonPressedUpdateEventDescriptionFailure(string eventTextFailure)
	{
		eventTextFadeCanvasGroup.Fade(toggle: false, delegate
		{
			eventText.SetText(eventTextFailure);
			InvokeAlternatives.InvokeAfterFrame(this, delegate
			{
				eventTextCanvasGroup.alpha = 1f;
				StartShowingEventText();
				CheckJoystick();
			});
		}, textsUpdateFadeOutDuration);
	}

	public string GetButtonPressedEventDescriptionSuccess(int buttonIndex)
	{
		return buttonCustomEventSetup.GetButtonPressedEventDescriptionSuccess(buttonIndex);
	}

	public string GetButtonPressedEventDescriptionFailure(int buttonIndex)
	{
		return buttonCustomEventSetup.GetButtonPressedEventDescriptionFailure(buttonIndex);
	}

	public void SetEventTextEmpty()
	{
		eventText.SetText("");
	}

	public void CleanEventDescriptionAndButtons(bool ignoreDisableRewardsAnimation = false)
	{
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation || ignoreDisableRewardsAnimation)
		{
			SetEventTextEmpty();
			SetButtonTextsToEmptyAndAlphaCanvasGroupToZero();
			StoreAllButtons();
		}
		else
		{
			CleanEventDescriptionAndButtonsWithFade();
		}
	}

	public void CleanEventDescriptionAndButtonsWithFade()
	{
		FadeCanvasGroupButtons();
		eventTextFadeCanvasGroup.Fade(toggle: false, delegate
		{
			StoreAllButtons();
		}, textsUpdateFadeOutDuration);
	}

	public void StoreWhenEnteredMap()
	{
		storeWhenEnteredMap = true;
	}

	public void OnUpdateUpdateEventDescriptionAndButtonsNotInstantly()
	{
		eventText.SetText(buttonCustomEventSetup.GetButtonPressedEventDescription(buttonPressedIndex));
		StoreAllButtons();
		InitializationLastButton(-1);
		InvokeAlternatives.Invoke(this, delayToUpdateEventText, delegate
		{
			StartShowingEventText();
			StartShowingLastButtonText();
			CheckJoystick();
		});
	}

	public void OnEnteredMap()
	{
		if (callOnEventButtonPressedButDontStoreEventsPanelState || storeWhenEnteredMap)
		{
			callOnEventButtonPressedButDontStoreEventsPanelState = false;
			storeWhenEnteredMap = false;
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
		}
	}

	public void OnFadeEventsPanelWithAction(bool value, Action afterFadeAction)
	{
		if (!ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
		{
			fadeCanvasGroup.Fade(value, afterFadeAction);
			return;
		}
		storeWhenEnteredMap = true;
		afterFadeAction?.Invoke();
	}

	public void OnFadeEventsPanelWithActionIgnoreDisableRewardsAnimation(bool value, Action afterFadeAction)
	{
		fadeCanvasGroup.Fade(value, afterFadeAction);
	}

	public void OnAfterRewardFadeInCanvasAndUpdateEventsPanel()
	{
		fadeCanvasGroup.Fade(toggle: true);
		comingBackFromFadeAction();
	}

	public void OnBackDuplicateDicePanelButtonPressed()
	{
		if (buttonCustomEventSetup.CanInitializeAgain)
		{
			Initialize(buttonCustomEventSetup);
		}
	}

	public void OnBackDestroyDicePanelButtonPressed()
	{
		if (buttonCustomEventSetup.CanInitializeAgain)
		{
			Initialize(buttonCustomEventSetup);
		}
	}

	public void OnBackForgeDicePanelButtonPressed()
	{
		if (buttonCustomEventSetup.CanInitializeAgain)
		{
			Initialize(buttonCustomEventSetup);
		}
	}

	public void OnEventButtonClick()
	{
		if (buttonCustomEventSetup.CanInitializeAgain)
		{
			OnShowBackButtonHideSkipButtonDiceRewardEvent.Raise();
		}
	}

	public void OnCompanionPreviewBackButtonPressed()
	{
		if (buttonCustomEventSetup.CanInitializeAgain && !(ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState))
		{
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.PlayerRewardState);
			Initialize(buttonCustomEventSetup);
		}
	}

	public List<ZoomableInstance> GetEventsButtonZoomableInstance()
	{
		List<ZoomableInstance> list = new List<ZoomableInstance>();
		List<Transform> children = eventButtonsHolder.GetChildren();
		for (int i = 0; i < children.Count; i++)
		{
			list.Add(children[i].GetComponent<EventButton>());
		}
		return list;
	}
}
